package wrapper_class;

public class Main {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		Integer value=90;  // Integer=> It is a wrapper class, used in type casting and collection
		Character letter='a';
		Boolean b=true;
		Float f=8.90f;
		Double d=8.098768;
		Long l=6626353l;
		Byte byt=34;
		Short s=87;
		
		//AutoBoxing => convert primitive data type to wrapper class 
		int a=87;
		Integer data=a;
		
		//UnBoxing => convert wrapper class to primitive data type
		Character word='a';
		char ch=word;
	}

}
